import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Navbar from './Components/Navbar/Navbar';
import Hero from './Components/Hero/Hero'; // Imported your new Amazon-style top header
import Footer from './Components/Footer/Footer';
import Home from './Pages/Home';
import LoginSignup from './Pages/LoginSignup';
import Products from './Pages/Products';
import About from './Pages/About';
import Contact from './Pages/Contact';
import Cart from './Pages/Cart';
import AdminDashboard from './Pages/AdminDashboard';
import ProtectedRoute from './Components/ProtectedRoute';
import SellerDashboard from './Pages/SellerDashboard';
import AddProductPage from './Pages/AddProductPage';
import Orders from './Pages/Orders';

function StoreLayout() {
  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', margin: 0, padding: 0, backgroundColor: '#f8f9fc' }}>
      {/* EMERGENCY STYLE OVERRIDE TO FORCE FULL WIDTH & KILL WHITESPACE */}
      <style>{`
        div[class*="-container"], div[class*="-page"], main {
          max-width: 100% !important;
          width: 100% !important;
          margin-left: 10 !important;
          margin-right: 0 !important;
          box-sizing: border-box !important; 
        }
      `}</style>

      {/* Sidebar Navigation */}
      <div style={{ width: '250px', minWidth: '250px', height: '100vh', position: 'sticky', top: '0', zIndex: 1000 }}>
        <Navbar />
      </div>

      {/* Right Side Content + Footer Area */}
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: '100vh', width: 'calc(100% - 250px)' }}>

        {/* Amazon-Style Top Bar (Search + Sub-nav links) */}
        <Hero />

        <main style={{ flex: 1, padding: '0', boxSizing: 'border-box', width: '100%' }}>
          <Routes>
            <Route path='/' element={<Home />} />
            <Route path='/products' element={<Products />} />
            <Route path='/about' element={<About />} />
            <Route path='/contact' element={<Contact />} />
            <Route path='/login' element={<LoginSignup />} />
            <Route path='/cart' element={<Cart />} />
            <Route path='/orders' element={<Orders />} />
          </Routes>
        </main>

        <Footer />
      </div>
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/seller/*" element={<SellerDashboard />} />
        <Route path="/seller" element={<SellerDashboard />} />
        <Route path="/seller/add-product" element={<AddProductPage />} />
        <Route 
          path="/admin" 
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminDashboard />
            </ProtectedRoute>
          } 
        />
        <Route path="/*" element={<StoreLayout />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
